#!/usr/bin/env bash
set -eo pipefail
source /data1/home/sunyiq/miniconda3/etc/profile.d/conda.sh
conda activate nh_final
set -u
export PYTHONDONTWRITEBYTECODE=1
python -B - <<'PY'
import base64,hashlib,json,pathlib,subprocess
root=pathlib.Path('/data1/home/sunyiq/zhenjiang_complete_comparison_20261006_recovery_001')
manifest=json.loads((root/'release_manifest.json').read_text())
for name,spec in manifest['files'].items():
 if hashlib.sha256((root/name).read_bytes()).hexdigest()!=spec['sha256']:raise ValueError('sealed recovery release changed')
if (root/'records/recovery_submission_attempt.json').exists():raise ValueError('submission previously attempted; inspect without repeating')
if (root/'records/recovery_preparation_complete.json').exists():raise ValueError('preparation already complete; inspect before submission')
raw=base64.b64decode('')
if hashlib.sha256(raw).hexdigest()!='e8709f783be370b956debdfb871efad9c54e9bfc0cf2f4dc14d2d11e1e0c32a8':raise ValueError('recovery preparation helper differs')
path=root/'hpc/prepare_recovery_v2.py'
with path.open('xb') as stream:stream.write(raw)
with (root/'records/recovery_preparation_attempt_002.json').open('x') as stream:
 json.dump({'helper_sha256':'e8709f783be370b956debdfb871efad9c54e9bfc0cf2f4dc14d2d11e1e0c32a8','repair':'Confirmed FAILED job may return Invalid job id from squeue.','original_helper_preserved':True},stream,indent=2)
subprocess.run(['python','-B',str(path)],cwd=root,check=True)
subprocess.run(['python','-B',str(root/'hpc/submit_recovery.py')],cwd=root,check=True)
PY
